#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "unity.h"
#include "gw_tls_check.h"

// Fixtures generated by tools/pki/make_test_fixtures.sh (hostname gatewayTEST), embedded at build time.
#define FIX(name) extern const char fx_##name[] asm("_binary_" #name "_start")
FIX(ca_crt); FIX(dev_key); FIX(dev_crt); FIX(dev_pkcs8_key); FIX(dev_rsa_key); FIX(dev_rsa_crt);
FIX(dev_other_name_crt); FIX(dev_client_eku_crt); FIX(dev_by_ca2_crt); FIX(int_crt);
FIX(dev_via_int_key); FIX(dev_via_int_crt); FIX(client_key);

#define HOST "gatewayTEST"

static void test_ok_ec(void)
{
    gw_tls_info_t info;
    TEST_ASSERT_NULL(gw_tls_check(fx_dev_key, fx_dev_crt, fx_ca_crt, HOST, &info));
    TEST_ASSERT_EQUAL_STRING("gatewayTEST", info.subject_cn);
    TEST_ASSERT_EQUAL_STRING("Gateway Root CA", info.issuer_cn);
    TEST_ASSERT_EQUAL_STRING("EC P-256", info.key_type);
    TEST_ASSERT_EQUAL(19, strlen(info.not_after));
}

static void test_ok_rsa(void)
{
    gw_tls_info_t info;
    TEST_ASSERT_NULL(gw_tls_check(fx_dev_rsa_key, fx_dev_rsa_crt, fx_ca_crt, HOST, &info));
    TEST_ASSERT_EQUAL_STRING("RSA 2048", info.key_type);
}

static void test_ok_pkcs8_key(void)
{
    gw_tls_info_t info;
    TEST_ASSERT_NULL(gw_tls_check(fx_dev_pkcs8_key, fx_dev_crt, fx_ca_crt, HOST, &info));
}

static void test_ok_chain_via_intermediate(void)
{
    gw_tls_info_t info;
    char *chain = malloc(strlen(fx_dev_via_int_crt) + strlen(fx_int_crt) + 1);
    strcpy(chain, fx_dev_via_int_crt);
    strcat(chain, fx_int_crt);
    TEST_ASSERT_NULL(gw_tls_check(fx_dev_via_int_key, chain, fx_ca_crt, HOST, &info));
    TEST_ASSERT_EQUAL_STRING("Gateway Intermediate CA", info.issuer_cn);
    free(chain);
}

static void test_crlf_and_whitespace(void)
{
    // "\n  " + cert with CRLF line ends + "  \r\n\n"
    size_t n = strlen(fx_dev_crt);
    char *messy = malloc(2 * n + 16), *p = messy;
    p += sprintf(p, "\n  ");
    for (size_t i = 0; i < n; i++) {
        if (fx_dev_crt[i] == '\n') {
            *p++ = '\r';
        }
        *p++ = fx_dev_crt[i];
    }
    strcpy(p, "  \r\n\n");
    gw_pem_normalize(messy);
    TEST_ASSERT_EQUAL('-', messy[0]);
    TEST_ASSERT_NULL(strchr(messy, '\r'));
    gw_tls_info_t info;
    TEST_ASSERT_NULL(gw_tls_check(fx_dev_key, messy, fx_ca_crt, HOST, &info));
    free(messy);
}

static void test_bad_inputs(void)
{
    gw_tls_info_t info;
    TEST_ASSERT_EQUAL_STRING("bad_key", gw_tls_check("garbage", fx_dev_crt, fx_ca_crt, HOST, &info));
    TEST_ASSERT_EQUAL_STRING("bad_key", gw_tls_check("", fx_dev_crt, fx_ca_crt, HOST, &info));
    TEST_ASSERT_EQUAL_STRING("bad_cert", gw_tls_check(fx_dev_key, "", fx_ca_crt, HOST, &info));
    TEST_ASSERT_EQUAL_STRING("bad_ca", gw_tls_check(fx_dev_key, fx_dev_crt, "", HOST, &info));
    // A device certificate is not a CA certificate.
    TEST_ASSERT_EQUAL_STRING("bad_ca", gw_tls_check(fx_dev_key, fx_dev_crt, fx_dev_crt, HOST, &info));
}

static void test_key_mismatch(void)
{
    gw_tls_info_t info;
    TEST_ASSERT_EQUAL_STRING("key_mismatch", gw_tls_check(fx_client_key, fx_dev_crt, fx_ca_crt, HOST, &info));
}

static void test_wrong_name(void)
{
    gw_tls_info_t info;
    TEST_ASSERT_EQUAL_STRING("wrong_name", gw_tls_check(fx_dev_key, fx_dev_other_name_crt, fx_ca_crt, HOST, &info));
    TEST_ASSERT_EQUAL_STRING("wrong_name", gw_tls_check(fx_dev_key, fx_dev_crt, fx_ca_crt, "gatewayTES", &info));
    // Case doesn't matter in DNS names.
    TEST_ASSERT_NULL(gw_tls_check(fx_dev_key, fx_dev_crt, fx_ca_crt, "GATEWAYtest", &info));
}

static void test_not_server_cert(void)
{
    gw_tls_info_t info;
    TEST_ASSERT_EQUAL_STRING("not_server_cert", gw_tls_check(fx_dev_key, fx_dev_client_eku_crt, fx_ca_crt, HOST, &info));
}

static void test_not_signed_by_ca(void)
{
    gw_tls_info_t info;
    TEST_ASSERT_EQUAL_STRING("not_signed_by_ca", gw_tls_check(fx_dev_key, fx_dev_by_ca2_crt, fx_ca_crt, HOST, &info));
}

void run_tls_check_tests(void)
{
    RUN_TEST(test_ok_ec);
    RUN_TEST(test_ok_rsa);
    RUN_TEST(test_ok_pkcs8_key);
    RUN_TEST(test_ok_chain_via_intermediate);
    RUN_TEST(test_crlf_and_whitespace);
    RUN_TEST(test_bad_inputs);
    RUN_TEST(test_key_mismatch);
    RUN_TEST(test_wrong_name);
    RUN_TEST(test_not_server_cert);
    RUN_TEST(test_not_signed_by_ca);
}
